export function main(input: any) {
  const acc: Record<string, { rep: string; visits: number; prospect: number }> = {};
  for (const it of input.items as any[]) {
    const rep = String(it.data?.rep ?? "未設定");
    const a = acc[rep] ?? (acc[rep] = { rep, visits: 0, prospect: 0 });
    a.visits += Number(it.data?.visits ?? 0);
    a.prospect += Number(it.data?.prospect ?? 0);
  }
  const rows = Object.values(acc)
    .sort((x, y) => x.rep.localeCompare(y.rep, "ja"))
    .map((a) => ({ week_start: input.start, rep: a.rep, visits: a.visits, prospect: a.prospect }));
  const lines = rows.map((r) => `${r.rep}: 訪問 ${r.visits} 件・見込み額 ${r.prospect}`).join("\n");
  return { rows, lines: lines === "" ? "（この週の日報はありません）" : lines };
}

function main(input) {
  const pick = (g, key) => {
    const e = Object.entries(g).find(([k]) => k.toLowerCase().includes(key));
    return e ? (Number(e[1]) || 0) : 0;
  };
  const groups = input.groups || [];
  const rows = groups.map(g => ({
    week_start: input.week_start,
    rep: g.rep ?? null,
    visits: pick(g, 'visit'),
    prospect: pick(g, 'prospect')
  }));
  const totalVisits = rows.reduce((s, r) => s + r.visits, 0);
  const totalProspect = rows.reduce((s, r) => s + r.prospect, 0);
  const lines = rows.map(r => `${r.rep ?? '（担当者未設定）'}: 訪問 ${r.visits} 件・見込み額 ${r.prospect} 円`);
  lines.push(`合計: 訪問 ${totalVisits} 件・見込み額 ${totalProspect} 円`);
  return { rows, total_visits: totalVisits, total_prospect: totalProspect, summary: lines.join('\n') };
}

function main(input) {
  const m = {};
  for (const it of input.items || []) {
    const d = it.data || {};
    const rep = d.rep || "（担当者なし）";
    if (!m[rep]) m[rep] = { rep: rep, visits: 0, prospect: 0 };
    m[rep].visits += Number(d.visits || 0);
    m[rep].prospect += Number(d.prospect || 0);
  }
  const rows = Object.keys(m).sort().map(k => ({ week_start: input.start, rep: m[k].rep, visits: m[k].visits, prospect: m[k].prospect }));
  const lines = rows.map(r => `| ${r.rep} | ${r.visits} | ${r.prospect} |`);
  const table = ["| 担当者 | 訪問件数 | 見込み額 |", "|---|---|---|"].concat(lines).join("\n");
  return { week_start: input.start, rows: rows, table: rows.length ? table : "（先週の日報はありません）" };
}

function main(input) {
  const map = new Map();
  for (const it of input.items) {
    const d = it.data;
    const rep = d.rep || '(担当者未入力)';
    if (!map.has(rep)) map.set(rep, { rep: rep, visits: 0, prospect: 0, notes: [] });
    const r = map.get(rep);
    r.visits += Number(d.visits || 0);
    r.prospect += Number(d.prospect || 0);
    if (d.note) r.notes.push(d.report_date + ': ' + d.note);
  }
  const rows = Array.from(map.values()).sort((a, b) => a.rep < b.rep ? -1 : a.rep > b.rep ? 1 : 0);
  const table_rows = rows.map(r => ({ week_start: input.start, rep: r.rep, visits: r.visits, prospect: r.prospect }));
  const report_input = rows.map(r => '担当者: ' + r.rep + '\n訪問件数の合計: ' + r.visits + '\n見込み額の合計: ' + r.prospect + '\n所感:\n' + (r.notes.length ? r.notes.map(n => '- ' + n).join('\n') : '- なし')).join('\n\n');
  return { table_rows: table_rows, report_input: report_input };
}

export function main(input) {
 const map = {};
 for (const it of input.items) {
 const d = it.data;
 const rep = d.rep || '（不明）';
 if (!map[rep]) map[rep] = { rep: rep, visits: 0, prospect: 0, notes: [] };
 map[rep].visits += Number(d.visits) || 0;
 map[rep].prospect += Number(d.prospect) || 0;
 if (d.note) map[rep].notes.push(d.note);
 }
 const list = Object.values(map).sort((a, b) => a.rep.localeCompare(b.rep, 'ja'));
 const rows = list.map(r => ({ week_start: input.week_start, rep: r.rep, visits: r.visits, prospect: r.prospect }));
 const text = list.map(r => '■ ' + r.rep + '\n訪問件数 ' + r.visits + ' 件 / 見込み額 ' + r.prospect + '\n所感: ' + (r.notes.join(' / ') || 'なし')).join('\n\n');
 return { week_start: input.week_start, rows: rows, text: text };
}

function main(input) {
  const sums = {};
  for (const it of input.items) {
    const d = it.data || {};
    const rep = d.rep ? String(d.rep) : '(担当者未入力)';
    if (!sums[rep]) sums[rep] = { visits: 0, prospect: 0 };
    sums[rep].visits += Number(d.visits) || 0;
    sums[rep].prospect += Number(d.prospect) || 0;
  }
  const reps = Object.keys(sums).sort();
  const rows = reps.map(rep => ({ week_start: input.week_start, rep: rep, visits: sums[rep].visits, prospect: sums[rep].prospect }));
  const lines = rows.map(r => r.rep + '： 訪問 ' + r.visits + ' 件・見込み額 ' + r.prospect + ' 円');
  const totalVisits = rows.reduce((a, r) => a + r.visits, 0);
  const totalProspect = rows.reduce((a, r) => a + r.prospect, 0);
  lines.push('合計： 訪問 ' + totalVisits + ' 件・見込み額 ' + totalProspect + ' 円');
  return { week_start: input.week_start, rows: rows, table_text: lines.join('\n'), report_count: input.items.length, total_visits: totalVisits, total_prospect: totalProspect };
}

function main(input) {
  const byRep = {};
  for (const it of (input.items || [])) {
    const d = it.data || {};
    const rep = d.rep || '(担当者不明)';
    if (!byRep[rep]) byRep[rep] = { rep: rep, visits: 0, prospect: 0 };
    byRep[rep].visits += Number(d.visits || 0);
    byRep[rep].prospect += Number(d.prospect || 0);
  }
  const rows = Object.keys(byRep).sort().map(function (k) {
    const r = byRep[k];
    return { week_start: input.start, rep: r.rep, visits: r.visits, prospect: r.prospect };
  });
  const table = rows.length
    ? rows.map(function (r) { return r.rep + '：訪問 ' + r.visits + ' 件・見込み額 ' + r.prospect; }).join('\n')
    : '（前週の日報はありません）';
  return { rows: rows, table: table };
}

