function main(input) {
  const items = (input.items || []).filter(r => {
    const d = r.data || {};
    return typeof d.qty === 'number' && typeof d.reorder_point === 'number' && d.qty < d.reorder_point;
  }).map(r => ({
    code: String(r.data.code ?? ''),
    name: String(r.data.name ?? ''),
    order_qty: Number(r.data.reorder_qty ?? 0),
    status: '下書き'
  }));
  const esc = v => { const s = String(v); return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
  const lines = ['品番,品名,発注数'].concat(items.map(r => [r.code, r.name, r.order_qty].map(esc).join(',')));
  return { count: items.length, items: items, csv: lines.join('\r\n') + '\r\n' };
}

function main(input) {
  const items = input.items || [];
  const picked = [];
  for (const it of items) {
    const d = it.data;
    if (d.qty !== null && d.reorder_point !== null && Number(d.qty) < Number(d.reorder_point)) {
      picked.push({ code: d.code, name: d.name, order_qty: d.reorder_qty });
    }
  }
  const esc = (v) => {
    const s = v === null || v === undefined ? '' : String(v);
    return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  const lines = ['品番,品名,発注数'].concat(picked.map(r => [r.code, r.name, r.order_qty].map(esc).join(',')));
  return {
    rows: picked.map(r => ({ code: r.code, name: r.name, order_qty: r.order_qty, status: '下書き' })),
    csv: lines.join('\n') + '\n'
