export function main(input) {
  const blank = (v) => (v === undefined || v === null || String(v).trim() === '') ? null : String(v).trim();
  const rows = (input.items || []).map((r) => {
    const keys = Object.keys(r);
    const pick = (names) => {
      const k = keys.find((x) => names.includes(String(x).trim()));
      return k === undefined ? null : blank(r[k]);
    };
    return { assignee: pick(['assignee', '担当', '担当者']), task: pick(['task', '作業', '作業内容', 'タスク']), due_on: pick(['due_on', '期限', '期日']) };
  }).filter((x) => x.task !== null);
  return { rows };
}

function main(input) {
  const r = Number(input.responses);
  const p = Number(input.promoters);
  const d = Number(input.detractors);
  if (!r) return { responses: r, promoters: p, detractors: d, nps: null };
  const raw = (p - d) / r * 100;
  const nps = Math.sign(raw) * Math.round(Math.abs(raw));
  return { responses: r, promoters: p, detractors: d, nps: nps };
}

function main(input) {
  const responses = Number(input.responses);
  const promoters = Number(input.promoters);
  const detractors = Number(input.detractors);
  const raw = ((promoters - detractors) / responses) * 100;
  const nps = raw < 0 ? -Math.round(-raw) : Math.round(raw);
  return { responses: responses, promoters: promoters, detractors: detractors, nps: nps };
}

